import importlib.util
import json
from pathlib import Path
import sys

import jax
import numpy as np
from jax.sharding import Mesh

root = Path(__file__).parent
results = []
for name in ('distributed_mace_scaling', 'pic_distributed'):
    spec = importlib.util.spec_from_file_location('baseline_' + name, root / ('baseline_' + name + '.py'))
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    if name == 'distributed_mace_scaling':
        try:
            module._plan(module._model(2), module._structure(16, 0)[0], 2, 16, 'devices')
        except Exception as error:
            results.append({'driver': name, 'case': 'five_visible_two_owners', 'exception': type(error).__name__, 'message': str(error)})
        else:
            raise AssertionError('Expected baseline subset-owner failure')
    else:
        for parts in (3, 5):
            blocks = module._block_shape('spectral-global-fft-blocks', parts)
            try:
                Mesh(np.asarray(jax.devices()[:parts]).reshape(module._mesh_shape(blocks)), tuple('xy'[:len(module._mesh_shape(blocks))]))
            except Exception as error:
                results.append({'driver': name, 'case': f'spectral_parts_{parts}', 'blocks': blocks, 'exception': type(error).__name__, 'message': str(error)})
            else:
                raise AssertionError('Expected baseline invalid mesh size')
(root / 'baseline_reproduce.json').write_text(json.dumps(results, indent=2))
print(json.dumps(results))

