"""Temporary transparent VJP instrumentation; GPU owner executes, no source edits."""
from __future__ import annotations

import argparse
from collections import defaultdict
from functools import partial
import json
from pathlib import Path
import runpy
from typing import Any

import jax
import jax.numpy as jnp
import numpy as np

from phydrax._polynomial import ProductGraphPlan
from phydrax.nn.atomistic._symmetric_contraction import SymmetricContractionBasis

ROOT = Path(__file__).resolve().parents[2]
fixture = runpy.run_path(str(ROOT / "tests/unit/atomistic/test_distributed_mace.py"))
original = SymmetricContractionBasis.path_features
identity_attribute = "basis_id"
captures: dict[str, list[tuple[np.ndarray, np.ndarray]]] = defaultdict(list)


def record(identity: str, values: Any, cotangent: Any) -> None:
    captures[identity].append((np.array(values), np.array(cotangent)))


@jax.custom_vjp
def instrumented(basis: Any, values: jax.Array) -> jax.Array:
    return original(basis, values)


def forward(basis: Any, values: jax.Array) -> tuple[jax.Array, Any]:
    return original(basis, values), (basis, values)


def backward(saved: Any, cotangent: jax.Array) -> Any:
    basis, values = saved
    jax.debug.callback(partial(record, getattr(basis, identity_attribute)), values, cotangent)
    _, pullback = jax.vjp(original, basis, values)
    return pullback(cotangent)


instrumented.defvjp(forward, backward)


def traced(basis: Any, values: jax.Array) -> jax.Array:
    return instrumented(basis, values)


def main() -> None:
    global original, identity_attribute
    parser = argparse.ArgumentParser()
    parser.add_argument("--target", choices=("projection", "product"), default="projection")
    parser.add_argument("--captures", type=Path)
    arguments = parser.parse_args()
    model = fixture["_model"](2)
    plan = fixture["_plan"](
        model, streaming_accumulation="deterministic", reduction="deterministic"
    )
    positions, species_ids = fixture["_structure"]()
    state = fixture["_prepare"](plan, model, positions, species_ids)
    if arguments.target == "projection":
        owner, method, identity_attribute = SymmetricContractionBasis, "path_features", "basis_id"
        bases = {
            basis.basis_id: basis
            for layer in model.layers
            for block in layer.product.contraction.plan.bases
            for basis in block
        }
    else:
        owner, method, identity_attribute = ProductGraphPlan, "evaluate", "plan_id"
        bases = {
            layer.product.contraction.plan.product_graph.plan_id:
            layer.product.contraction.plan.product_graph
            for layer in model.layers
        }
    original = getattr(owner, method)
    if arguments.captures is None:
        setattr(owner, method, traced)
        try:
            result = fixture["evaluate_owner_local_atomistic"](plan, model, state)
            jax.block_until_ready(result)
            if not bool(result.successful):
                raise ValueError("Instrumented evaluation failed.")
        finally:
            setattr(owner, method, original)
        archive = {
            f"{identity}/values": np.stack([sample[0] for sample in samples])
            for identity, samples in captures.items()
        } | {
            f"{identity}/cotangents": np.stack([sample[1] for sample in samples])
            for identity, samples in captures.items()
        }
        path = Path(__file__).with_name(f"mace_{arguments.target}_captures.npz")
        np.savez_compressed(path, **archive)
        print(f"Captured exact operands: {path}", flush=True)
    else:
        with np.load(arguments.captures) as archive:
            for identity in bases:
                if f"{identity}/values" in archive:
                    captures[identity] = list(zip(
                        archive[f"{identity}/values"],
                        archive[f"{identity}/cotangents"], strict=True,
                    ))
    for identity, samples in captures.items():
        basis = bases[identity]
        values = jnp.asarray(np.stack([sample[0] for sample in samples]))
        cotangents = jnp.asarray(np.stack([sample[1] for sample in samples]))

        def transpose(rows: jax.Array, cotangent: jax.Array) -> jax.Array:
            _, pullback = jax.vjp(lambda value: original(basis, value), rows)
            return pullback(cotangent)[0]

        compiled = jax.jit(jax.vmap(transpose))
        expected = np.asarray(compiled(values, cotangents))
        for repeat in range(5):
            actual = np.asarray(compiled(values, cotangents))
            finite = np.isfinite(actual) & np.isfinite(expected)
            difference = np.where(finite, actual, 0.0) - np.where(finite, expected, 0.0)
            print(json.dumps({
                "comparison": f"actual {arguments.target} cotangent replay",
                "identity": identity,
                "samples": len(samples),
                "repeat": repeat,
                "finite_elements": int(np.count_nonzero(finite)),
                "different_finite_elements": int(np.count_nonzero(finite & (actual != expected))),
                "matching_nonfinite_patterns": bool(
                    np.array_equal(np.isnan(actual), np.isnan(expected))
                    and np.array_equal(np.isposinf(actual), np.isposinf(expected))
                    and np.array_equal(np.isneginf(actual), np.isneginf(expected))
                ),
                "maximum_finite_absolute_difference": float(np.max(np.abs(difference))),
            }), flush=True)


if __name__ == "__main__":
    main()

