from pathlib import Path
import runpy
import sys
from typing import Any

import equinox as eqx
import jax
import jax.numpy as jnp
import numpy as np

root = Path(__file__).resolve().parents[2]
namespace = runpy.run_path(str(root / "tests/unit/solver/test_distributed_pic.py"))
print("DEVICES", jax.devices(), flush=True)
mesh = namespace["_mesh"]((2, 2))
base, _ = namespace["_spectral_base"](
    32, mesh, "global-fft", subdomains=(4, 2, 1), counts=(16, 16, 4)
)
values = jnp.asarray(
    np.random.default_rng(7).normal(size=(16, 16, 4, 11)), dtype=jnp.float64
)


@eqx.filter_jit
def field_roundtrip(transform: Any, value: jax.Array) -> jax.Array:
    return transform.inverse(transform.forward(value)[..., :6])


@eqx.filter_jit
def field_and_divergence_roundtrip(transform: Any, value: jax.Array) -> jax.Array:
    field = transform.inverse(transform.forward(value)[..., :6])
    return transform.inverse(transform.forward(field)[..., :2])


cases = (
    ("11-forward-6-inverse", field_roundtrip, 6),
    ("11-forward-6-inverse-6-forward-2-inverse", field_and_divergence_roundtrip, 2),
)
alone = len(sys.argv) > 1 and sys.argv[1] == "alone"
if alone:
    cases = cases[1:]
for name, operation, width in cases:
    print("LOWER", name, flush=True)
    compiled = operation.lower(base.transform, values).compile()
    suffix = "alone_all5" if alone else "masked"
    (root / f".tmp/h200-qualification/pic_fft_{name}_{suffix}_hlo.txt").write_text(
        compiled.compiled.as_text()
    )
    print("EXECUTE", name, flush=True)
    actual = jax.block_until_ready(compiled(base.transform, values))
    np.testing.assert_allclose(actual, np.asarray(values)[..., :width], rtol=1e-12, atol=1e-12)
    print("PASS", name, flush=True)
